const casePanel=document.createElement('section');casePanel.className='editor';casePanel.innerHTML='<h2>Shared scenario</h2><label>Choose a case<select id="case-select"><option value="">New case</option></select></label><form id="case-form"><div class="form-grid"><label>Subject<input id="case-subject" list="subjects" required maxlength="100"></label><label>Topic<input id="case-topic" list="case-topics" required maxlength="100"><datalist id="case-topics"></datalist></label></div><p id="case-category-impact" class="hint"></p><label>Case ID<input id="case-key" required maxlength="50" placeholder="S001"></label><label>Case title (visible to learners)<input id="case-title" required placeholder="Patient with fever and flank pain"></label><label>History<textarea id="case-history" required rows="4"></textarea></label><label>Physical examination<textarea id="case-examination" rows="3"></textarea></label><label>Laboratory findings<textarea id="case-laboratory" rows="3"></textarea></label><button class="primary" id="save-case">Save shared case</button><p id="case-message" role="status"></p></form>';document.querySelector('.admin-grid').before(casePanel);
function caseOptions(){const chosen=$('case-id').value;$('case-id').innerHTML='<option value="">Standalone question</option>'+caseBank.map(c=>`<option value="${esc(c.id)}">${esc(c.id)} — ${esc(c.title)}</option>`).join('');$('case-id').value=chosen;$('case-select').innerHTML='<option value="">New case</option>'+caseBank.map(c=>`<option value="${esc(c.id)}">${esc(c.id)} — ${esc(c.title)}</option>`).join('');}
